#!/usr/bin/env node
// Provision (or roll back) the Desktop twin in the DSH Desktop profile.
//
// The change is strictly additive and reversible:
//   - `package.json` gains ONE dependency (`link:` to this workspace) and ONE
//     bundle name; nothing else is touched;
//   - `pnpm-lock.yaml` is regenerated by pnpm itself;
//   - `node_modules` gains the link directory pnpm creates;
//   - everything else in the profile (trisoul_x, the -desktop web-search twin,
//     the profile patch layer, the Web profile) is left alone.
//
// Usage:
//   node scripts/profile-wiring.mjs --check      # report, change nothing
//   node scripts/profile-wiring.mjs --apply      # back up, edit, pnpm install
//   node scripts/profile-wiring.mjs --rollback   # restore the backups
//
// After --apply the Desktop app must be restarted: `dsh.profile.bundles` is read
// once at startup, so a new bundle cannot be picked up live.
import { copyFileSync, existsSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { spawnSync } from 'node:child_process'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const PACKAGE_NAME = '@dsh-external/dsh-task-notifier-desktop'
const ROW_ID = 'task-notifier-desktop'
const PACKAGE_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const DSH_HOME = process.env.DSH_HOME ?? 'D:/DeepseekHome'
const PROFILE_DIR = join(DSH_HOME, 'profiles', 'desktop')
const PROFILE_JSON = join(PROFILE_DIR, 'package.json')
const LOCKFILE = join(PROFILE_DIR, 'pnpm-lock.yaml')
const BACKUP_SUFFIX = '.bak-before-task-notifier-desktop'
const LINK_SPEC = `link:${PACKAGE_ROOT.replaceAll('\\', '/')}`

const mode = process.argv.includes('--rollback') ? 'rollback'
  : process.argv.includes('--apply') ? 'apply'
    : process.argv.includes('--check') ? 'check'
      : null
if (mode === null) {
  console.error('usage: node scripts/profile-wiring.mjs [--check|--apply|--rollback]')
  process.exit(2)
}

const readJson = path => JSON.parse(readFileSync(path, 'utf8'))

/** Everything the DSH client-modules resolver needs to find our client bundle. */
function inspectWiring() {
  const manifest = readJson(PROFILE_JSON)
  const dependency = manifest.dependencies?.[PACKAGE_NAME]
  const bundled = (manifest.dsh?.profile?.bundles ?? []).includes(PACKAGE_NAME)
  const installedManifestPath = join(PROFILE_DIR, 'node_modules', '@dsh-external', 'dsh-task-notifier-desktop', 'package.json')
  const installed = existsSync(installedManifestPath)
  let clientOk = false
  let bannerId
  if (installed) {
    const installedManifest = readJson(installedManifestPath)
    const clientRel = installedManifest.exports?.['./client']?.default
    clientOk = installedManifest.name === PACKAGE_NAME
      && installedManifest.dsh?.client?.platform === 'web'
      && typeof clientRel === 'string'
      && existsSync(join(dirname(installedManifestPath), clientRel))
    if (clientOk) {
      const bundledClient = readFileSync(join(dirname(installedManifestPath), clientRel), 'utf8')
      bannerId = /window\.__ModuleLoader__\.load\(\{\s*id:\s*"([^"]+)"/.exec(bundledClient)?.[1]
      clientOk = bannerId === PACKAGE_NAME
    }
  }
  return { manifest, dependency, bundled, installed, clientOk, bannerId, installedManifestPath }
}

function report(state) {
  const lines = [
    `profile            ${PROFILE_DIR}`,
    `dependency         ${state.dependency ?? '(absent)'}`,
    `bundle listed      ${state.bundled ? 'yes' : 'no'}`,
    `node_modules link  ${state.installed ? 'present' : 'absent'}`,
    `client resolved    ${state.clientOk ? `yes (banner ${state.bannerId})` : 'no'}`,
    `loader row         ${ROW_ID}`,
    `backups            ${existsSync(PROFILE_JSON + BACKUP_SUFFIX) ? 'taken' : 'not taken'}`,
  ]
  console.log(lines.join('\n'))
}

function runPnpmInstall() {
  console.log('\n$ pnpm install --no-frozen-lockfile --prefer-offline')
  const result = spawnSync('pnpm', ['install', '--no-frozen-lockfile', '--prefer-offline'], {
    cwd: PROFILE_DIR,
    stdio: 'inherit',
    shell: true,
  })
  if (result.status !== 0) {
    console.error(`\npnpm install failed with status ${result.status}`)
    process.exit(result.status ?? 1)
  }
}

const state = inspectWiring()

if (mode === 'check') {
  report(state)
  const wired = state.dependency === LINK_SPEC && state.bundled && state.installed && state.clientOk
  console.log(`\n${wired ? 'WIRED' : 'NOT WIRED'}`)
  process.exit(wired ? 0 : 1)
}

if (mode === 'apply') {
  if (state.dependency === LINK_SPEC && state.bundled && state.installed && state.clientOk) {
    console.log('already wired; nothing to do\n')
    report(state)
    process.exit(0)
  }
  // The backup is the rollback anchor. Reuse it when the profile still matches
  // it (the normal state after `--rollback`); refuse when the profile has since
  // diverged, because overwriting would destroy the anchor.
  for (const target of [PROFILE_JSON, LOCKFILE]) {
    if (!existsSync(target)) continue
    const backup = target + BACKUP_SUFFIX
    const label = target.slice(PROFILE_DIR.length + 1)
    if (!existsSync(backup)) {
      copyFileSync(target, backup)
      console.log(`backed up ${label} → ${label}${BACKUP_SUFFIX}`)
      continue
    }
    if (readFileSync(target, 'utf8') === readFileSync(backup, 'utf8')) {
      console.log(`reusing existing ${label}${BACKUP_SUFFIX} (profile unchanged since it was taken)`)
      continue
    }
    console.error(`refusing: ${label}${BACKUP_SUFFIX} exists and differs from the current ${label};`
      + ' inspect the profile and resolve manually before re-applying')
    process.exit(1)
  }

  const manifest = state.manifest
  manifest.dependencies ??= {}
  manifest.dependencies[PACKAGE_NAME] = LINK_SPEC
  // Keep dependency keys sorted the way pnpm writes them.
  manifest.dependencies = Object.fromEntries(Object.entries(manifest.dependencies).sort(([a], [b]) => a.localeCompare(b)))
  manifest.dsh ??= {}
  manifest.dsh.profile ??= {}
  manifest.dsh.profile.bundles ??= []
  if (!manifest.dsh.profile.bundles.includes(PACKAGE_NAME)) manifest.dsh.profile.bundles.push(PACKAGE_NAME)
  writeFileSync(PROFILE_JSON, `${JSON.stringify(manifest, null, 2)}\n`)
  console.log(`added dependency ${PACKAGE_NAME} = ${LINK_SPEC}`)
  console.log('appended it to dsh.profile.bundles')

  runPnpmInstall()

  const after = inspectWiring()
  report(after)
  const wired = after.dependency === LINK_SPEC && after.bundled && after.installed && after.clientOk
  if (!wired) {
    console.error('\nwiring incomplete — inspect the profile before restarting the app')
    process.exit(1)
  }
  console.log('\nWIRED. Restart the Desktop app so it picks up the new bundle.')
  process.exit(0)
}

if (mode === 'rollback') {
  if (!existsSync(PROFILE_JSON + BACKUP_SUFFIX)) {
    console.error(`no backup at ${PROFILE_JSON + BACKUP_SUFFIX}; nothing to roll back`)
    process.exit(1)
  }
  // Rollback is only safe from the wired state, or from a state that still
  // matches the backup. Otherwise it would silently destroy edits made after
  // `--apply`.
  const diverged = [PROFILE_JSON, LOCKFILE]
    .filter(target => existsSync(target) && existsSync(target + BACKUP_SUFFIX)
      && readFileSync(target, 'utf8') !== readFileSync(target + BACKUP_SUFFIX, 'utf8'))
    .map(target => target.slice(PROFILE_DIR.length + 1))
  const wasWired = state.dependency === LINK_SPEC && state.bundled && state.installed
  if (diverged.length > 0 && !wasWired) {
    console.error(`refusing to roll back: ${diverged.join(', ')} changed since the backup was taken.`
      + ' Inspect the profile and restore manually, or delete the backup once you are sure.')
    process.exit(1)
  }
  if (diverged.length > 0) {
    console.warn(`overwriting ${diverged.join(', ')} (currently wired; the backup holds the pre-change state)`)
  }

  copyFileSync(PROFILE_JSON + BACKUP_SUFFIX, PROFILE_JSON)
  console.log(`restored ${PROFILE_JSON}`)
  if (existsSync(LOCKFILE + BACKUP_SUFFIX)) {
    copyFileSync(LOCKFILE + BACKUP_SUFFIX, LOCKFILE)
    console.log(`restored ${LOCKFILE}`)
  }
  const linkDir = join(PROFILE_DIR, 'node_modules', '@dsh-external', 'dsh-task-notifier-desktop')
  if (existsSync(linkDir)) {
    rmSync(linkDir, { recursive: true, force: true })
    console.log(`removed ${linkDir}`)
  }
  // pnpm may leave the stale entry in the hoisted store; a plain install re-syncs.
  runPnpmInstall()
  const after = inspectWiring()
  report(after)
  const rolledBack = after.dependency === undefined && !after.bundled && !after.installed
  console.log(`\n${rolledBack ? 'ROLLED BACK' : 'STILL WIRED — inspect manually'}`)
  process.exit(rolledBack ? 0 : 1)
}